// ─── Bodies and clocks ─────────────────────────────────────────────────────

type BodyKey = keyof typeof fixtures.bodies;
type Json = Record<string, unknown>;
const raw = (key: BodyKey): string => fixtures.bodies[key].raw;
const parsed = (key: BodyKey): Json => JSON.parse(raw(key)) as Json;
const detail = (key: BodyKey) => parsed(key) as unknown as EventDetailResponse;
const history = (key: BodyKey) => parsed(key) as unknown as EventHistoryResponse;
const markets = (key: BodyKey) => parsed(key) as unknown as GameMarketsResponse;

const HULL_NOW = Date.parse(fixtures.provenance.clocks.hullNow);
const LIVE_NOW = Date.parse(fixtures.provenance.clocks.liveNow);
const FINAL_NOW = Date.parse(fixtures.provenance.clocks.finalNow);
const LIVE_LATER_NOW = LIVE_NOW + 40 * 60 * 1000;
const EXACT_PRE_NOW = Date.parse(fixtures.provenance.clocks.exactPreKickoffNow);
const EXACT_LIVE_NOW = Date.parse(fixtures.provenance.clocks.exactLiveNow);
const EXACT_FINAL_NOW = Date.parse(fixtures.provenance.clocks.exactFinalNow);

/** CONSTRUCTED owner metadata (see the header): the native tests' own ids. */
const C = fixtures.constructed as unknown as {
  liveAdmission: SoccerMatchAdmission;
  hullAdmission: SoccerMatchAdmission;
  fullTotals: number[];
  hullDescriptor: NonNullable<SoccerMatchAdmission["exactScore"]>;
};
const LIVE_ADMISSION = C.liveAdmission;
const HULL_ADMISSION = C.hullAdmission;
const HULL_BEFORE_ADMISSION: SoccerMatchAdmission = {
  ...HULL_ADMISSION,
  goals: C.fullTotals,
  exactScore: C.hullDescriptor,
};

/** Native `F.edited`: the body with only the named keys removed or set. */
function edited<T>(body: T, setting: Json = {}, removing: string[] = []): T {
  const copy = JSON.parse(JSON.stringify(body)) as Json;
  for (const key of removing) delete copy[key];
  Object.assign(copy, setting);
  return copy as unknown as T;
}

/** Native `F.editedRow`: one row (by its single contributor id) with only the named fields set. */
function editedRow(body: GameMarketsResponse, outcomeId: number, setting: Json, array = "other"): GameMarketsResponse {
  const copy = JSON.parse(JSON.stringify(body)) as Json;
  const rows = copy[array] as Json[];
  const index = rows.findIndex((row) => JSON.stringify(row.contributor_outcome_ids) === JSON.stringify([outcomeId]));
  if (index < 0) throw new Error(`no ${array} row for ${outcomeId}`);
  rows[index] = { ...rows[index], ...setting };
  return copy as unknown as GameMarketsResponse;
}

/** Native `F.graded`: the named rows carrying a venue settlement. */
function graded(body: GameMarketsResponse, outcomes: Record<number, boolean>): GameMarketsResponse {
  let out = body;
  for (const [id, won] of Object.entries(outcomes)) {
    out = editedRow(out, Number(id), { is_winner: won, resolution_source: "api_settlement" });
  }
  return out;
}

/** The page's own hero pair, as page.tsx resolves it (no chart point, no preview). */
function pageHero(event: EventDetailResponse, held: EventHistoryResponse, isLive: boolean) {
  const resolved = resolveProbability(event, held, null, isLive, false, false, false, true);
  return {
    homeProb: resolved.homeProb,
    awayProb: resolved.awayProb,
    homePct: resolved.homePct,
    awayPct: resolved.awayPct,
    probSourceLabel: resolved.probSourceLabel,
  };
}

function host(event: EventDetailResponse, held: EventHistoryResponse, nowMs: number, extra: Partial<SoccerMatchHost> = {}): SoccerMatchHost {
  return {
    nowMs,
    hero: pageHero(event, held, event.status === "live"),
    probabilityObservedAt: event.hero_probability_observed_at ?? null,
    ...extra,
  };
}

const pct = (value: number) => formatProbabilityPercent(value);
const pregameValue = (p: SoccerPregame) => (p.kind === "value" ? p.observation.probability : null);
const pregameWords = (p: SoccerPregame) => (p.kind === "missing" ? p.words : null);
const currentValue = (c: SoccerCurrent | null) => (c?.kind === "recorded" ? c.observation.probability : null);
const won: SoccerResult = { kind: "won" };
const lost: SoccerResult = { kind: "lost" };
const unknown: SoccerResult = { kind: "unconfirmed", words: READING_WORDS.resultUnavailable };

const hull = detail("hullDetail");
const live = detail("liveDetail");
const final = detail("finalDetail");
const hullFinal = detail("hullFinalDetail");
const liveNames = soccerNames(live);

// ─── Provenance ────────────────────────────────────────────────────────────

describe("#10868 soccer fixture provenance", () => {
  it("every body is the native fixture's own bytes at the recorded commit", () => {
    const repo = join(__dirname, "..", "..", "..");
    for (const [key, file] of Object.entries(fixtures.provenance.files)) {
      const swift = readFileSync(join(repo, file.path));
      // The Swift file is the one the bodies were copied from (sha256 at 274369bc).
      expect({ key, sha256: createHash("sha256").update(swift).digest("hex") }).toEqual({ key, sha256: file.sha256 });
    }
    for (const [key, body] of Object.entries(fixtures.bodies)) {
      expect({ key, sha256: createHash("sha256").update(body.raw, "utf8").digest("hex") }).toEqual({ key, sha256: body.sha256 });
      const swift = readFileSync(join(repo, fixtures.provenance.files[body.file as "retained" | "exact"].path), "utf8");
      expect({ key, occurrences: swift.split(body.raw).length - 1 }).toEqual({ key, occurrences: 1 });
    }
  });

  it("the four detail bodies are the retained captures native pins byte for byte", () => {
    expect(fixtures.bodies.hullDetail.sha256).toBe("05aba8d16e2ac82c2ba7e1a64471918c96e76e93821d893c324ecfaa989f0eab");
    expect(fixtures.bodies.liveDetail.sha256).toBe("e14790d9ec05a49f4b241cc8e9cd3cd1290f14a14cfe6eeb52053a2b94de4645");
    expect(fixtures.bodies.finalDetail.sha256).toBe("2a365c2f197d33eb75d10c6acc65532f1b3afe7bb0e7361dd56dfae0bf74fa90");
    expect(fixtures.bodies.hullFinalDetail.sha256).toBe("613123df55db40fe308eef46d51ae07da1e035653622b8bc9870e7048d231f9d");
  });

  it("decodes the subsets native counts", () => {
    expect(hull.id).toBe(15311089);
    expect(live.home_score).toBe(4);
    expect(final.home_score).toBe(5);
    expect(history("hullHistory").aggregate_line).toHaveLength(7);
    expect(history("liveHistory").score_history).toHaveLength(5);
    expect(history("finalHistory").aggregate_line).toHaveLength(27);
    expect(markets("liveMarkets").other).toHaveLength(14);
    expect(markets("liveMarkets").totals).toHaveLength(4);
  });

  it("the CONSTRUCTED owner metadata carries native's ids and nothing in production supplies it", () => {
    expect(LIVE_ADMISSION.goals).toEqual([64353423, 64353425, 64536538]);
    expect(LIVE_ADMISSION.halves.map((h) => h.marketId)).toEqual([63178219, 63178218]);
    expect(C.hullDescriptor.scopes.map((s) => s.originals.length)).toEqual([37, 9]);
    expect(NO_SOCCER_ADMISSION).toEqual({ goals: [], both: null, first: null, halves: [], ownClockGoals: [], exactScore: null });
  });
});

