describe("#10868 soccer — header", () => {
  it("before kickoff: kickoff words, no score, no clock, projection unavailable", () => {
    const header = soccerMatchHeader(hull, "before", history("hullHistory"), HULL_NOW);
    const start = Date.parse(hull.commence_time);
    expect(header.state).toBe(MATCH_WORDS.beforeKickoff);
    expect(header.date).toBe(`${dayWords(start)} · Kickoff ${timeWords(start)}`);
    expect(header.score).toBeNull();
    expect(header.clock).toBeNull();
    expect(header.projection?.reading).toEqual({ kind: "unavailable", text: MATCH_WORDS.projectionUnavailable });
  });

  it("CONSTRUCTED start_is_tbd: the kickoff time is to be announced", () => {
    const header = soccerMatchHeader(edited(hull, { start_is_tbd: true }), "before", null, HULL_NOW);
    expect(header.date).toBe(`${dayWords(Date.parse(hull.commence_time))} · ${MATCH_WORDS.kickoffToBeAnnounced}`);
  });

  it("during play: the score keeps its own clock and the match clock is unavailable", () => {
    const header = soccerMatchHeader(live, "live", history("liveHistory"), LIVE_NOW);
    expect(header.state).toBe(MATCH_WORDS.inPlay);
    expect(header.score).toEqual({
      kind: "actual",
      home: "4",
      away: "0",
      context: `Score observed ${clockWords(live.score_observed_at)}`,
      spoken: `${liveNames.home} 4, ${liveNames.away} 0`,
    });
    expect(header.clock).toEqual({ kind: "unavailable", text: MATCH_WORDS.clockUnavailable });
    // No in-play projection object is served: never the ladders' or the sportsbooks' pair.
    expect(header.projection?.reading).toEqual({ kind: "unavailable", text: MATCH_WORDS.projectionUnavailable });
  });

  it("after the final: the served winner and the final score", () => {
    const header = soccerMatchHeader(final, "final", history("finalHistory"), FINAL_NOW);
    expect(header.state).toBe(`Final · ${liveNames.home} won`);
    expect(header.score).toEqual({ kind: "actual", home: "5", away: "0", context: "Final score", spoken: `Final: ${liveNames.home} 5, ${liveNames.away} 0` });
    expect(header.clock).toBeNull();
    expect(header.projection?.reading).toEqual({ kind: "unavailable", text: MATCH_WORDS.projectionUnavailable });
  });

  it("Design parity case 2 — Hull–Everton's 2–2 final shows the DRAW as the result", () => {
    const header = soccerMatchHeader(hullFinal, "final", null, EXACT_FINAL_NOW);
    expect(header.state).toBe(`Final · ${MATCH_WORDS.draw}`);
    expect(header.score).toMatchObject({ kind: "actual", home: "2", away: "2", context: "Final score" });
  });

  it("CONSTRUCTED home_score removed: a missing score is the slot's words, never 0", () => {
    expect(soccerMatchHeader(edited(live, {}, ["home_score"]), "live", null, LIVE_NOW).score).toEqual({
      kind: "unavailable",
      text: MATCH_WORDS.scoreUnavailable,
    });
  });
});

// ─── Headline ──────────────────────────────────────────────────────────────

describe("#10868 soccer — three-outcome headline (native `headline`)", () => {
  it("before kickoff: the hero's home value, rounded alone; Draw and the away win keep their words", () => {
    const h = soccerMatchHeadline(hull, "before", host(hull, history("hullHistory"), HULL_NOW));
    expect(h.outcomes.map((o) => o.label)).toEqual([`${soccerNames(hull).home} win`, "Draw", `${soccerNames(hull).away} win`]);
    expect(h.outcomes[0].primary).toEqual({ kind: "value", text: pct(0.265) });
    expect(h.primaryHeading).toEqual({ title: MATCH_WORDS.currentWinChance, context: `Recorded ${clockWords(hull.hero_probability_observed_at)}` });
    expect(h.comparisonHeading).toBeNull();
    expect(h.outcomes[1].primary).toEqual({ kind: "unavailable", text: MATCH_WORDS.drawChanceUnavailable });
    expect(h.outcomes[2].primary).toEqual({ kind: "unavailable", text: MATCH_WORDS.awayChanceUnavailable });
  });

  it("Design parity case 1 — during play (hero_probability 0.995, away null): no invented away or draw chance", () => {
    expect(live.hero_probability).toBe(0.995);
    expect(live.hero_probability_away).toBeNull();
    const held = host(live, history("liveHistory"), LIVE_NOW);
    // The page's own pair carries a complement away (1 − 0.995); the headline never reads it.
    expect(held.hero?.awayProb).toBeCloseTo(0.005, 6);
    const h = soccerMatchHeadline(live, "live", held);
    expect(h.outcomes[0].primary).toEqual({ kind: "value", text: pct(0.995) });
    expect(h.primaryHeading.title).toBe(MATCH_WORDS.currentWinChance);
    expect(h.outcomes[2].primary).toEqual({ kind: "unavailable", text: MATCH_WORDS.awayChanceUnavailable });
    expect(h.outcomes[1].primary).toEqual({ kind: "unavailable", text: MATCH_WORDS.drawChanceUnavailable });
    // prematch_odds is null on this body: the reading is opening_odds, named an opening chance.
    expect(h.comparisonHeading).toEqual({ title: MATCH_WORDS.openingChance, context: null });
    expect(h.outcomes[0].comparison).toEqual({ kind: "value", text: pct(0.4929) });
    // The opening object's OWN away (0.2278) — a sourced earlier reading, never 1 − home.
    expect(h.outcomes[2].comparison).toEqual({ kind: "value", text: pct(0.2278) });
    expect(h.outcomes[1].comparison).toEqual({ kind: "unavailable", text: MATCH_WORDS.drawChanceUnavailable });
    const printed = JSON.stringify(h);
    expect(printed).not.toContain(`"${pct(0.005)}"`);
    expect(printed).not.toContain(`"${pct(1 - 0.4929 - 0.2278)}"`);
  });

  it("CONSTRUCTED opening away null / out of range / 0: no away is printed and no complement takes its place", () => {
    for (const away of [null, 1.2, 0]) {
      const body = edited(live, { opening_odds: { home_probability: 0.4929, away_probability: away, spread: -0.5, over_under: 2.5, favorite: "home" } });
      const h = soccerMatchHeadline(body, "live", host(body, history("liveHistory"), LIVE_NOW));
      expect(h.outcomes[0].comparison).toEqual({ kind: "value", text: pct(0.4929) });
      expect(h.outcomes[2].comparison).toEqual({ kind: "unavailable", text: MATCH_WORDS.awayChanceUnavailable });
    }
  });

  it("CONSTRUCTED delivery interrupted: the pair is last recorded", () => {
    const h = soccerMatchHeadline(live, "live", host(live, history("liveHistory"), LIVE_NOW, { deliveryInterrupted: true }));
    expect(h.primaryHeading.title).toBe(MATCH_WORDS.lastRecordedWinChance);
  });

  it("after the final: the pre-match chance leads, the served away is withheld, the settled 1.0 is never the headline", () => {
    const h = soccerMatchHeadline(final, "final", host(final, history("finalHistory"), FINAL_NOW));
    expect(h.primaryHeading).toEqual({ title: MATCH_WORDS.preMatchChance, context: "Polymarket" });
    expect(h.outcomes[0].primary).toEqual({ kind: "value", text: pct(0.51) });
    expect(h.outcomes[2].primary).toEqual({ kind: "unavailable", text: MATCH_WORDS.awayChanceUnavailable });
    expect(h.comparisonHeading).toBeNull();
    expect(h.outcomes[0].primary.text).not.toBe(pct(1));
  });

  it("Design parity case 2 — the settled 0.5 / 0.5 never becomes a pre-match chance on Hull–Everton's 2–2 final", () => {
    expect(hullFinal.hero_probability).toBe(0.5);
    expect(hullFinal.hero_probability_away).toBe(0.5);
    expect(hullFinal.hero_probability_source).toBe("settled");
    const h = soccerMatchHeadline(hullFinal, "final", { nowMs: EXACT_FINAL_NOW, hero: { homeProb: 0.5, awayProb: 0.5, homePct: 50, awayPct: 50 }, probabilityObservedAt: null });
    // The stored pre-match evidence: the served Kalshi ladder (home 0.225).
    expect(h.primaryHeading).toEqual({ title: MATCH_WORDS.preMatchChance, context: "Kalshi" });
    expect(h.outcomes[0].primary).toEqual({ kind: "value", text: pct(0.225) });
    expect(h.outcomes[2].primary).toEqual({ kind: "unavailable", text: MATCH_WORDS.awayChanceUnavailable });
    expect(h.outcomes[1].primary).toEqual({ kind: "unavailable", text: MATCH_WORDS.drawChanceUnavailable });
    expect(JSON.stringify(h)).not.toContain(`"${pct(0.5)}"`);
  });

  it("CONSTRUCTED prematch and opening removed: unavailable, never 'not recorded'", () => {
    const body = edited(final, {}, ["prematch_odds", "opening_odds"]);
    const h = soccerMatchHeadline(body, "final", host(body, history("finalHistory"), FINAL_NOW));
    expect(h.primaryHeading.title).toBe(MATCH_WORDS.preMatchChance);
    expect(h.outcomes[0].primary).toEqual({ kind: "unavailable", text: "Pre-match chance unavailable" });
    expect(JSON.stringify(h)).not.toContain("not recorded");
  });
});

// ─── History ───────────────────────────────────────────────────────────────

describe("#10868 soccer — history (native `SoccerHistoryAdapter10868`)", () => {
  it("during play only the home win is drawn; Draw and the away win keep their words", () => {
    const h = soccerMatchHistory(history("liveHistory"), live, "live", LIVE_NOW);
    expect([h.home.id, h.draw.id, h.away.id]).toEqual(["blend:15325054:home", "blend:15325054:draw", "blend:15325054:away"]);
    expect([h.home.name, h.draw.name, h.away.name]).toEqual([`${liveNames.home} win`, "Draw", `${liveNames.away} win`]);
    expect(h.draw.words).toBe(SOCCER_HISTORY_WORDS.drawHistoryUnavailable);
    expect(h.away.words).toBe(SOCCER_HISTORY_WORDS.awayHistoryUnavailable);
    expect(h.notes).toContain(SOCCER_HISTORY_WORDS.drawAndAwayNote(liveNames.away));
    expect(h.summary.endsWith(SOCCER_HISTORY_WORDS.drawAndAwayNote(liveNames.away))).toBe(true);
    expect(h.summary.startsWith(`${liveNames.home} win chance, recorded observations only.`)).toBe(true);
  });

  it("the line starts at the last pre-match reading and breaks across the unrecorded span", () => {
    const h = soccerMatchHistory(history("liveHistory"), live, "live", LIVE_NOW);
    const id = "blend:15325054:home#";
    const runs = h.home.runs.map((run) => run.map((p) => p.id));
    expect(runs).toHaveLength(2);
    expect(runs[0][0]).toBe(`${id}2026-10-12T11:59:00+00:00`);
    expect(runs[0][runs[0].length - 1]).toBe(`${id}2026-10-12T12:09:00+00:00`);
    expect(runs[1][0]).toBe(`${id}2026-10-12T12:52:00+00:00`);
    expect(runs[1][runs[1].length - 1]).toBe(`${id}2026-10-12T12:55:00+00:00`);
    expect(runs.flat()).not.toContain(`${id}2026-10-12T12:56:02.476915+00:00`);
    expect(runs.flat()).not.toContain(`${id}2026-10-12T12:56:00+00:00`);
    expect(h.home.runs[0][0].hollow).toBe(true);
  });

  it("the readout pairs the last pre-match reading with the latest recorded one", () => {
    const h = soccerMatchHistory(history("liveHistory"), live, "live", LIVE_NOW);
    expect(h.caption).toBe(SOCCER_HISTORY_WORDS.gameCaption);
    expect(h.readout).toBe("beforeAndRecorded");
    expect([h.beforeLabel, h.recordedLabel]).toEqual([SOCCER_HISTORY_WORDS.preMatch, SOCCER_HISTORY_WORDS.recorded]);
    expect(h.home.before).toEqual({
      kind: "reading",
      figure: pct(0.4892),
      provenance: `${SOCCER_HISTORY_WORDS.lastPreMatch} · ${clockWords("2026-10-12T11:59:00+00:00")}`,
      pointId: "blend:15325054:home#2026-10-12T11:59:00+00:00",
    });
    expect(h.home.recorded).toEqual({
      kind: "reading",
      figure: pct(0.951805),
      provenance: `Recorded ${clockWords("2026-10-12T12:55:00+00:00")}`,
      pointId: "blend:15325054:home#2026-10-12T12:55:00+00:00",
    });
    expect(h.markKey).toBe(SOCCER_HISTORY_WORDS.hollowKey);
    expect(h.absence).toBeNull();
  });

  it("before kickoff the line ends at the last pre-match reading and omits the pinned edge", () => {
    const h = soccerMatchHistory(history("hullHistory"), hull, "before", HULL_NOW);
    const id = "blend:15311089:home#";
    expect(h.caption).toBe(SOCCER_HISTORY_WORDS.beforeCaption);
    expect(h.readout).toBe("single");
    expect(h.beforeLabel).toBe(SOCCER_HISTORY_WORDS.preMatch);
    expect(h.home.runs.map((run) => run.map((p) => p.id))).toEqual([
      [
        `${id}2026-10-10T04:57:00+00:00`,
        `${id}2026-10-10T05:03:00+00:00`,
        `${id}2026-10-10T05:07:00+00:00`,
        `${id}2026-10-11T04:53:00+00:00`,
        `${id}2026-10-11T04:54:00+00:00`,
        `${id}2026-10-11T04:56:00+00:00`,
      ],
    ]);
    expect(h.guides).toEqual([]);
  });

  it("after the final the settlement row is not drawn as a chance", () => {
    const h = soccerMatchHistory(history("finalHistory"), final, "final", FINAL_NOW);
    const points = h.home.runs.flat();
    expect(h.readout).toBe("single");
    expect(points.some((p) => p.p === 1)).toBe(false);
    expect(points[points.length - 1].p).toBe(0.9995);
    expect(h.home.runs).toHaveLength(3);
  });

  it("CONSTRUCTED aggregate_line removed: on the consensus the served away figure is still never drawn", () => {
    const h = soccerMatchHistory(edited(history("liveHistory"), {}, ["aggregate_line"]), live, "live", LIVE_NOW);
    expect(h.home.id).toBe("consensus:15325054:home");
    expect(h.home.runs.length).toBeGreaterThan(0);
    expect(h.away.words).toBe(SOCCER_HISTORY_WORDS.awayHistoryUnavailable);
    expect(h.notes[0]).toBe(HISTORY_WORDS.consensusSource);
  });

  it("CONSTRUCTED event_id changed: another event's history reads exactly as none", () => {
    const foreign = soccerMatchHistory(edited(history("liveHistory"), { event_id: 15325055 }), live, "live", LIVE_NOW);
    expect(foreign).toEqual(soccerMatchHistory(null, live, "live", LIVE_NOW));
  });

  it("with no history response only the chart slot says so", () => {
    const h = soccerMatchHistory(undefined, live, "live", LIVE_NOW);
    expect(h.absence).toEqual({ title: SOCCER_HISTORY_WORDS.historyUnavailable, words: null });
    expect(h.home.runs).toEqual([]);
    expect([h.home.before, h.draw.words, h.away.words]).toEqual([
      { kind: "absent", words: "History unavailable" },
      "History unavailable",
      "History unavailable",
    ]);
    expect(h.notes).toEqual([]);
  });
});

