describe("#10868 soccer — exact final score (CONSTRUCTED descriptor)", () => {
  const map = (event: EventDetailResponse, body: GameMarketsResponse, nowMs: number): SoccerExactCard =>
    soccerExactCard(event, body, HULL_BEFORE_ADMISSION, soccerMatchPhase(event, nowMs), soccerNames(event), nowMs)!;
  const scope = (card: SoccerExactCard, id: string): SoccerExactScope => card.scopes.find((s) => s.id === id)!;
  const original = (s: SoccerExactScope, id: string): SoccerExactOriginal => s.originals.find((o) => o.id === id)!;
  const listed = (id: string) => C.hullDescriptor.scopes.find((s) => s.id === id)!.originals.map((o) => o.outcomeIds.join("+"));

  it("before kickoff every listed score of both scopes is on the map with its own chance and clock", () => {
    const card = map(hull, markets("hullExactMarkets"), EXACT_PRE_NOW);
    expect(card.title).toBe(EXACT_WORDS.title);
    expect(EXACT_WORDS.title).toBe("How might it finish?");
    expect(card.intro).toBe(EXACT_WORDS.beforeIntro);
    expect(card.scopes.map((s) => [s.id, s.label])).toEqual([
      ["full", "Full match"],
      ["first", "First half"],
    ]);
    expect(card.defaultScopeId).toBe("full");
    const full = scope(card, "full");
    const first = scope(card, "first");
    expect(full.originals.map((o) => o.id)).toEqual(listed("full"));
    expect(first.originals.map((o) => o.id)).toEqual(listed("first"));
    expect(full.originals.filter((o) => o.placement.kind === "nonGrid").map((o) => o.id)).toEqual(["245266693"]);
    expect(first.originals.some((o) => o.placement.kind === "grid" && o.placement.home === 2 && o.placement.away === 2)).toBe(false);
    // Never normalised: the full match keeps its raw pre-match sum.
    const sum = full.originals.reduce((n, o) => n + (pregameValue(o.pregame) ?? 0), 0);
    expect(sum).toBeCloseTo(1.0001, 7);
    expect(original(full, "237459055").pregame).toMatchObject({ kind: "value", observation: { text: pct(0.0398) } });
    expect(full.actual).toBeNull();
    expect(full.originals.every((o) => o.current === null && o.result === null)).toBe(true);
  });

  it("at the body's capture instant every quote is too old to show, and every score stays listed", () => {
    const card = map(hull, markets("hullExactMarkets"), HULL_NOW);
    expect(card.scopes.map((s) => s.originals.length)).toEqual([37, 9]);
    expect(card.scopes.every((s) => s.originals.every((o) => pregameWords(o.pregame) === READING_WORDS.noRecentUpdate))).toBe(true);
  });

  it("CONSTRUCTED live variant: an own-clocked recent full-match quote is current; a first-half quote stays dated history", () => {
    const stamp = "2026-10-11T13:15:00+00:00";
    const event = edited(hull, { status: "live", home_score: 1, away_score: 0, score_observed_at: "2026-10-11T13:14:00+00:00" });
    let body = editedRow(markets("hullExactMarkets"), 238846931, { observed_at: stamp });
    body = editedRow(body, 244588607, { observed_at: stamp });
    const card = map(event, body, EXACT_LIVE_NOW);
    // During play the map still asks how it might finish.
    expect(card.title).toBe("How might it finish?");
    expect(card.intro).toBe(EXACT_WORDS.liveIntro);
    const full = scope(card, "full");
    expect(original(full, "238846931").current).toMatchObject({ kind: "recorded", observation: { probability: 0.0952 } });
    expect(original(full, "238846934").current).toEqual({ kind: "unavailable", words: READING_WORDS.inPlayUnavailable });
    expect(pregameWords(original(full, "238846931").pregame)).toBe(READING_WORDS.preMatchNotRecorded);
    expect(original(scope(card, "first"), "244588607").current).toEqual({
      kind: "withheld",
      words: `In-play chance unavailable · ${pct(0.307)} recorded ${clockWords(stamp)} · Polymarket`,
    });
    const names = soccerNames(event);
    expect(full.actual).toEqual({ title: EXACT_WORDS.scoreSoFar, text: `${names.home} 1–0 ${names.away} · observed ${clockWords("2026-10-11T13:14:00+00:00")}` });
    expect(scope(card, "first").actual).toBeNull();
  });

  it("Design parity case 2 — after Hull–Everton's 2–2 final the draw is the one HIT and no settled value is a pre-match chance", () => {
    const card = map(hullFinal, markets("hullFinalMarkets"), EXACT_FINAL_NOW);
    // A completed game speaks in the past tense; nothing else on the card changes with it.
    expect(card.title).toBe("How it finished");
    expect(EXACT_WORDS.finalTitle).toBe("How it finished");
    expect(card.intro).toBe(EXACT_WORDS.finalIntro);
    const full = scope(card, "full");
    expect(full.originals.map((o) => o.id)).toEqual(listed("full"));
    expect(full.originals.filter((o) => o.result?.kind === "won").map((o) => o.id)).toEqual(["237459055"]);
    expect(full.originals.filter((o) => o.result?.kind === "lost")).toHaveLength(36);
    expect(full.originals.every((o) => pregameWords(o.pregame) === READING_WORDS.preMatchUnavailable)).toBe(true);
    const names = soccerNames(hullFinal);
    expect(full.actual).toEqual({ title: EXACT_WORDS.finalScore, text: `${names.home} 2–2 ${names.away}` });
    // The first-half family has left the payload: all nine held by the owner's labels, unconfirmed, no figure.
    const first = scope(card, "first");
    expect(first.originals.map((o) => o.id)).toEqual(listed("first"));
    expect(first.originals.every((o) => o.held && JSON.stringify(o.result) === JSON.stringify(unknown))).toBe(true);
    expect(first.originals.every((o) => pregameWords(o.pregame) === READING_WORDS.preMatchUnavailable)).toBe(true);
    expect(first.actual).toBeNull();
  });

  it("another event's descriptor or markets admit nothing", () => {
    expect(soccerExactCard(live, markets("hullExactMarkets"), HULL_BEFORE_ADMISSION, "live", liveNames, LIVE_NOW)).toBeNull();
    expect(soccerExactCard(hull, markets("liveMarkets"), HULL_BEFORE_ADMISSION, "before", soccerNames(hull), EXACT_PRE_NOW)).toBeNull();
  });
});

