describe("#10868 soccer — route-phase membership (native `routeCards` / `offers`)", () => {
  it("is the approved table, and an explicit halves admission adds the card in any phase", () => {
    expect(routeCards("before")).toEqual(["goals", "exact"]);
    expect(routeCards("live")).toEqual(["goals", "both", "first"]);
    expect(routeCards("final")).toEqual(["goals", "both", "first", "halves"]);
    expect(offersStory("halves", "live", [], "routeDefault")).toBe(false);
    expect(offersStory("halves", "before", [], "explicit")).toBe(true);
    expect(offersStory("exact", "live", ["exact"], "routeDefault")).toBe(true);
  });
});

describe("#10868 soccer — the composed page (`buildSoccerMatch`)", () => {
  const build = (
    event: EventDetailResponse,
    held: EventHistoryResponse | null,
    body: GameMarketsResponse | null,
    nowMs: number,
    admitted?: SoccerMatchAdmission,
    extra: { halvesAdmission?: "routeDefault" | "explicit" } = {},
  ) =>
    buildSoccerMatch({
      event,
      history: held,
      gameMarkets: body,
      admitted,
      ...extra,
      host: host(event, held ?? history("liveHistory"), nowMs),
    });

  it("REAL INPUTS (no admission): the headline, history and All props run; every story is the owner-unavailable state", () => {
    const page = build(live, history("liveHistory"), markets("liveMarkets"), LIVE_NOW);
    expect(page.stories.cards).toEqual([]);
    expect(page.stories.manualStatus).toBeNull();
    expect(page.stories.emptyWords).toBe(STORY_WORDS.emptyWords);
    expect(page.headline.outcomes[0].primary).toEqual({ kind: "value", text: pct(0.995) });
    expect(page.history.home.runs.length).toBeGreaterThan(0);
    expect(page.originals.originals.length).toBeGreaterThan(0);
    expect(page.copy.allPropsLabel).toBe(`All props · ${page.originals.originals.length}`);
  });

  it("CONSTRUCTED admission, during play: goals, both and first, in the fixed order; halves only when admitted", () => {
    const page = build(live, history("liveHistory"), markets("liveMarkets"), LIVE_NOW, LIVE_ADMISSION);
    expect(page.stories.cards.map((c) => c.id)).toEqual(["goals", "both", "first"]);
    expect(page.stories.cards.map((c) => c.name)).toEqual([STORY_WORDS.goals, STORY_WORDS.both, STORY_WORDS.first]);
    expect(page.stories.manualStatus).toBe(STORY_WORDS.manualStatus);
    const explicit = build(live, history("liveHistory"), markets("liveMarkets"), LIVE_NOW, LIVE_ADMISSION, { halvesAdmission: "explicit" });
    expect(explicit.stories.cards.map((c) => c.id)).toEqual(["goals", "both", "first", "halves"]);
  });

  it("the stories carry one reading scope per event and phase, and each card its own unavailable-choice words (native)", () => {
    const during = build(live, history("liveHistory"), markets("liveMarkets"), LIVE_NOW, LIVE_ADMISSION, { halvesAdmission: "explicit" });
    const after = build(final, history("finalHistory"), markets("finalMarkets"), FINAL_NOW, LIVE_ADMISSION);
    const before = build(hull, history("hullHistory"), markets("hullExactMarkets"), EXACT_PRE_NOW, HULL_BEFORE_ADMISSION);
    // SoccerPageInputAdapter10868.scope: "soccer:<event id>:<phase>".
    expect(during.stories.scope).toBe(`soccer:${live.id}:live`);
    expect(after.stories.scope).toBe(`soccer:${final.id}:final`);
    expect(before.stories.scope).toBe(`soccer:${hull.id}:before`);
    expect(build(live, history("liveHistory"), markets("liveMarkets"), LIVE_NOW).stories.scope).toBe(during.stories.scope);
    const words = (page: typeof during) =>
      page.stories.cards.map((c) => [c.id, c.id === "exact" ? [c.scopeUnavailable, c.selectionUnavailable] : c.selectionUnavailable]);
    expect(words(during)).toEqual([
      ["goals", "Selected milestone unavailable."],
      ["both", "Selected outcome unavailable."],
      ["first", "Selected outcome unavailable."],
      ["halves", "Selected outcome unavailable."],
    ]);
    expect(words(before)).toEqual([
      ["goals", "Selected milestone unavailable."],
      ["exact", ["Selected market unavailable.", "Selected score unavailable."]],
    ]);
  });

  it("CONSTRUCTED admission, after the final: no goal rows kept, so both, first, halves", () => {
    const page = build(final, history("finalHistory"), markets("finalMarkets"), FINAL_NOW, LIVE_ADMISSION);
    expect(page.stories.cards.map((c) => c.id)).toEqual(["both", "first", "halves"]);
  });

  it("CONSTRUCTED admission, before kickoff: the goal outlook (no over row on these bodies) and the exact map; never halves", () => {
    const page = build(hull, history("hullHistory"), markets("hullExactMarkets"), EXACT_PRE_NOW, HULL_BEFORE_ADMISSION);
    expect(page.stories.cards.map((c) => c.id)).toEqual(["goals", "exact"]);
    expect(page.stories.cards[0].name).toBe(STORY_WORDS.goalOutlook);
    expect(page.stories.cards.some((c) => c.id === "halves")).toBe(false);
  });

  it("another match's history and markets never reach this one", () => {
    const page = build(live, edited(history("liveHistory"), { event_id: 1 }), edited(markets("liveMarkets"), { event_id: 1 }), LIVE_NOW, LIVE_ADMISSION);
    expect(page.history.absence?.title).toBe(SOCCER_HISTORY_WORDS.historyUnavailable);
    expect(page.originals.originals).toEqual([]);
    expect(page.copy.allPropsLabel).toBeNull();
    expect(page.stories.cards).toEqual([]);
  });
});

// ─── All props ─────────────────────────────────────────────────────────────

describe("#10868 soccer — All props (native `SoccerOriginalsAdapter10868`)", () => {
  const halvesSet = new Set(LIVE_ADMISSION.halves.map((h) => h.marketId));
  const find = (o: ReturnType<typeof soccerMatchOriginals>, market: string, side: string) =>
    o.originals.find((x) => x.identity.source === "polymarket" && x.identity.market === market && x.identity.side === side)!;

  it("every served original is listed once under one scope per phase", () => {
    const o = soccerMatchOriginals(live, markets("liveMarkets"), LIVE_NOW);
    expect(o.scope).toBe("soccer:15325054:live:originals");
    expect(new Set(o.originals.map((x) => x.key)).size).toBe(o.originals.length);
    expect(o.heading).toBe(SOCCER_ORIGINALS_WORDS.heading);
    expect(o.context).toBe(SOCCER_ORIGINALS_WORDS.context(o.originals.length));
    expect(o.originals.every((x) => x.mode === "current")).toBe(true);
  });

  it("a sibling-clocked totals quote is historical, never current; its pre-match chance is the stored pin", () => {
    const over = find(soccerMatchOriginals(live, markets("liveMarkets"), LIVE_NOW), "64353425", "242143187");
    expect(over.later).toEqual({ kind: "missing", words: ORIGINALS_WORDS.noRecentPrice });
    expect(over.about.historical?.text).toBe(pct(0.15));
    expect(over.about.historical?.recorded).toBe(`${clockWords("2026-10-12T12:55:39.585325+00:00")} · Polymarket`);
    expect(over.pregame).toEqual({
      kind: "value",
      text: pct(0.13),
      placement: 0.13,
      provenance: `${SOCCER_ORIGINALS_WORDS.savedBeforeStart} ${clockWords("2026-10-12T11:47:12.057085+00:00")} · Polymarket`,
    });
  });

  it("an own-clocked recent quote is the current chance beside its pin", () => {
    const yes = find(soccerMatchOriginals(live, markets("liveMarkets"), LIVE_NOW), "64353426", "242143189");
    expect(yes.later).toEqual({ kind: "value", text: pct(0.49), placement: 0.49, provenance: `Recorded ${clockWords("2026-10-12T12:54:58.549918+00:00")} · Polymarket` });
    expect(yes.about.historical).toBeNull();
    expect(yes.pregame).toMatchObject({ placement: 0.55 });
  });

  it("CONSTRUCTED half admission: an admitted half's recent quote is dated history, never current; without it the row is not known to be a half", () => {
    const admitted = soccerMatchOriginals(live, markets("liveMarkets"), LIVE_NOW, halvesSet);
    const home = find(admitted, "63178219", "242338171");
    expect(home.later).toEqual({ kind: "missing", words: READING_WORDS.inPlayUnavailable });
    expect(home.about.historical?.text).toBe(pct(0.999));
    expect(home.about.historical?.recorded).toBe(`${clockWords(FIRST_HALF_STAMP)} · Polymarket`);
    const plain = find(soccerMatchOriginals(live, markets("liveMarkets"), LIVE_NOW), "63178219", "242338171");
    expect(plain.later).toEqual({ kind: "value", text: pct(0.999), placement: 0.999, provenance: `Recorded ${clockWords(FIRST_HALF_STAMP)} · Polymarket` });
  });

  it("CONSTRUCTED undated half quote keeps no historical quote; a graded half has no chance", () => {
    const undated = find(soccerMatchOriginals(live, editedRow(markets("liveMarkets"), 242338171, { observed_at: null }), LIVE_NOW, halvesSet), "63178219", "242338171");
    expect(undated.later).toEqual({ kind: "missing", words: ORIGINALS_WORDS.noRecentPrice });
    expect(undated.about.historical).toBeNull();
    const gradedHalf = find(soccerMatchOriginals(live, graded(markets("liveMarkets"), { 242338171: true }), LIVE_NOW, halvesSet), "63178219", "242338171");
    expect(gradedHalf.later).toEqual({ kind: "missing", words: READING_WORDS.settledNoChance });
    expect(gradedHalf.about.historical).toBeNull();
  });

  it("after the final each original shows its own venue grade, never a chance", () => {
    const o = soccerMatchOriginals(final, markets("finalMarkets"), FINAL_NOW);
    const no = find(o, "64353426", "242143190");
    const yes = find(o, "64353426", "242143189");
    expect(no.mode).toBe("result");
    expect(no.later).toBeNull();
    expect(no.grade).toEqual({ hit: true, words: PROP_HIT_LABEL, provenance: "Settled by Polymarket" });
    expect(yes.grade).toEqual({ hit: false, words: PROP_MISS_LABEL, provenance: "Settled by Polymarket" });
    expect(no.pregame).toEqual({ kind: "missing", words: READING_WORDS.preMatchUnavailable });
    expect(find(soccerMatchOriginals(final, markets("finalMarkets"), FINAL_NOW, halvesSet), "63178219", "242338171").grade).toEqual({
      hit: true,
      words: PROP_HIT_LABEL,
      provenance: "Settled by Polymarket",
    });
  });

  it("CONSTRUCTED live Hull: 'not recorded' only where the producer says no pin was recorded", () => {
    const body = edited(hull, { status: "live" });
    const said = find(soccerMatchOriginals(body, markets("hullMarkets"), HULL_NOW), "62939466", "238846913");
    expect(said.pregame).toEqual({ kind: "missing", words: READING_WORDS.preMatchNotRecorded });
  });

  it("CONSTRUCTED unsupported matrix: no pin is read, every original is still listed", () => {
    const real = soccerMatchOriginals(live, markets("liveMarkets"), LIVE_NOW);
    const body = markets("liveMarkets");
    const unsupported = edited(body, { game_question_matrix: { ...(body.game_question_matrix as unknown as Json), contract: "10238.v2" } });
    const o = soccerMatchOriginals(live, unsupported, LIVE_NOW);
    expect(o.originals.map((x) => x.key)).toEqual(real.originals.map((x) => x.key));
    expect(find(o, "64353426", "242143189").pregame).toEqual({ kind: "missing", words: READING_WORDS.preMatchUnavailable });
    expect(find(o, "64353426", "242143189").later).toMatchObject({ placement: 0.49 });
  });

  it("before kickoff only a recent own-clocked quote is the pre-match chance", () => {
    const o = soccerMatchOriginals(hull, markets("hullMarkets"), HULL_NOW);
    expect(o.scope).toBe("soccer:15311089:before:originals");
    const yes = find(o, "63390540", "238847205");
    expect(yes.mode).toBe("pregame");
    expect(yes.pregame).toEqual({ kind: "value", text: pct(0.535), placement: 0.535, provenance: `Recorded ${clockWords("2026-10-11T04:37:08.994633+00:00")} · Polymarket` });
    expect(find(o, "62939466", "238846913").pregame).toEqual({ kind: "missing", words: ORIGINALS_WORDS.noRecentPrice });
  });

  it("no markets response lists nothing and says so", () => {
    const o = soccerMatchOriginals(live, null, LIVE_NOW);
    expect(o.originals).toEqual([]);
    expect(o.context).toBeNull();
    expect(o.emptyWords).toBe(SOCCER_ORIGINALS_WORDS.emptyWords);
  });
});

const FIRST_HALF_STAMP = "2026-10-12T12:54:07.360375+00:00";

/**
 * Non-vacuity for the settled-vocabulary census enrolment
 * (`settledVocabulary.test.tsx`, `soccerMatch(hit)`): the same CONSTRUCTED pair
 * — the final body with every row's settlement forced one way and the matrix
 * options' own `result` removed — offers stories and graded originals to render,
 * so the census's hit/miss comparison is never over an empty page.
 */
describe("#10868 soccer — the census's forced pair has verdicts to state", () => {
  function forced(hit: boolean) {
    const body = parsed("finalMarkets");
    for (const key of ["totals", "spreads", "team_totals", "period_markets", "other"]) {
      body[key] = ((body[key] as Json[] | undefined) ?? []).map((row) => ({ ...row, is_winner: hit, resolution_source: "api_settlement" }));
    }
    const matrix = body.game_question_matrix as Json;
    matrix.questions = (matrix.questions as Json[]).map((q) => ({
      ...q,
      options: (q.options as Json[]).map((o) => {
        const rest = { ...o };
        delete rest.result;
        return rest;
      }),
    }));
    return buildSoccerMatch({
      event: final,
      history: history("finalHistory"),
      gameMarkets: body as unknown as GameMarketsResponse,
      admitted: LIVE_ADMISSION,
      host: { nowMs: FINAL_NOW, hero: null, probabilityObservedAt: null },
    });
  }

  it("offers both, first and halves, and grades originals both ways", () => {
    expect(forced(true).stories.cards.map((c) => c.id)).toEqual(["both", "first", "halves"]);
    expect(forced(true).originals.originals.some((o) => o.grade?.hit === true)).toBe(true);
    expect(forced(false).originals.originals.some((o) => o.grade?.hit === false)).toBe(true);
  });
});
